79	/// A wrapper around the `simctl` command line tool.
80	class SimControl {
81	  SimControl({
82	    @required Logger logger,
83	    @required ProcessManager processManager,
84	  }) : _logger = logger,
85	       _processUtils = ProcessUtils(processManager: processManager, logger: logger);
86	
87	  final Logger _logger;
88	  final ProcessUtils _processUtils;
89	
90	  /// Runs `simctl list --json` and returns the JSON of the corresponding
91	  /// [section].
92	  Future<Map<String, dynamic>> _list(SimControlListSection section) async {
93	    // Sample output from `simctl list --json`:
94	    //
95	    // {
96	    //   "devicetypes": { ... },
97	    //   "runtimes": { ... },
98	    //   "devices" : {
99	    //     "com.apple.CoreSimulator.SimRuntime.iOS-8-2" : [
100	    //       {
101	    //         "state" : "Shutdown",
102	    //         "availability" : " (unavailable, runtime profile not found)",
103	    //         "name" : "iPhone 4s",
104	    //         "udid" : "1913014C-6DCB-485D-AC6B-7CD76D322F5B"
105	    //       },
106	    //       ...
107	    //   },
108	    //   "pairs": { ... },
109	
110	    final List<String> command = <String>[_xcrunPath, 'simctl', 'list', '--json', section.name];
111	    _logger.printTrace(command.join(' '));
112	    final RunResult results = await _processUtils.run(command);
113	    if (results.exitCode != 0) {
114	      _logger.printError('Error executing simctl: ${results.exitCode}\n${results.stderr}');
115	      return <String, Map<String, dynamic>>{};
116	    }
117	    try {
118	      final Object decodeResult = json.decode(results.stdout?.toString())[section.name];
119	      if (decodeResult is Map<String, dynamic>) {
120	        return decodeResult;
121	      }
122	      _logger.printError('simctl returned unexpected JSON response: ${results.stdout}');
123	      return <String, dynamic>{};
124	    } on FormatException {
125	      // We failed to parse the simctl output, or it returned junk.
126	      // One known message is "Install Started" isn't valid JSON but is
127	      // returned sometimes.
128	      _logger.printError('simctl returned non-JSON response: ${results.stdout}');
129	      return <String, dynamic>{};
130	    }
131	  }
132	
133	  /// Returns a list of all available devices, both potential and connected.
134	  Future<List<SimDevice>> getDevices() async {
135	    final List<SimDevice> devices = <SimDevice>[];
136	
137	    final Map<String, dynamic> devicesSection = await _list(SimControlListSection.devices);
138	
139	    for (final String deviceCategory in devicesSection.keys) {
140	      final Object devicesData = devicesSection[deviceCategory];
141	      if (devicesData != null && devicesData is List<dynamic>) {
142	        for (final Map<String, dynamic> data in devicesData.map<Map<String, dynamic>>(castStringKeyedMap)) {
143	          devices.add(SimDevice(deviceCategory, data));
144	        }
145	      }
146	    }
147	
148	    return devices;
149	  }
150	
151	  /// Returns all the connected simulator devices.
152	  Future<List<SimDevice>> getConnectedDevices() async {
153	    final List<SimDevice> simDevices = await getDevices();
154	    return simDevices.where((SimDevice device) => device.isBooted).toList();
155	  }
